'@
$b64 = $b64 -replace '\s',''
$pagePath = Join-Path $repo $slug
[System.IO.File]::WriteAllBytes($pagePath, [Convert]::FromBase64String($b64))
Write-Host ("Page written: " + (Test-Path $pagePath)) -ForegroundColor Yellow

# ---- 2. blog.html card (inserted after the last existing article-card block) ----
$blogPath = Join-Path $repo "blog.html"
$blog = [System.IO.File]::ReadAllText($blogPath, $utf8)
if ($blog.Contains($slug)) {
  Write-Host "blog.html already has the card - skipped" -ForegroundColor Yellow
} else {
  $card = @'
<div class="article-card">
  <div class="article-title"><a href="6-types-of-fried-fish.html">6 Types of Fried Fish: Indian Fish Fry Recipes</a></div>
  <div class="article-meta">Recipes &bull; Indian Cuisine</div>
  <div class="article-excerpt">Rava fry, Amritsari, Surmai Tawa Masala, Kerala style, Spiced Pomfret and Bengali Machher Chop, with ingredients, method, frying science and food safety tips.</div>
  <a class="read-more-btn" href="6-types-of-fried-fish.html">Read Article &rarr;</a>
  <span class="badge">Newest</span>
</div>
'@
  $ms = [regex]::Matches($blog, '<(div|article)\b[^>]*class="[^"]*\barticle-card\b[^"]*"[^>]*>')
  if ($ms.Count -eq 0) {
    Write-Host "No article-card found in blog.html - add this card manually:" -ForegroundColor Red
    Write-Host $card
  } else {
    $last = $ms[$ms.Count - 1]
    $tag = $last.Groups[1].Value
    $tok = [regex]("<" + $tag + "\b|</" + $tag + "\s*>")
    $depth = 0; $endIdx = -1
    foreach ($t in $tok.Matches($blog.Substring($last.Index))) {
      if ($t.Value.StartsWith("</")) { $depth-- } else { $depth++ }
      if ($depth -eq 0) { $endIdx = $last.Index + $t.Index + $t.Length; break }
    }
    if ($endIdx -lt 0) { throw "Could not find end of last article-card block" }
    $blog = $blog.Insert($endIdx, "`r`n" + $card)
    [System.IO.File]::WriteAllText($blogPath, $blog, $utf8)
    Write-Host "blog.html card inserted" -ForegroundColor Yellow
  }
}

# ---- 3. sitemap.xml entry ----
$smPath = Join-Path $repo "sitemap.xml"
$sm = [System.IO.File]::ReadAllText($smPath, $utf8)
if ($sm.Contains($slug)) {
  Write-Host "sitemap.xml already has the entry - skipped" -ForegroundColor Yellow
} else {
  $entry = "  <url>`r`n    <loc>$base/$slug</loc>`r`n    <lastmod>2026-09-29</lastmod>`r`n    <changefreq>monthly</changefreq>`r`n    <priority>0.8</priority>`r`n  </url>`r`n"
  $i = $sm.LastIndexOf("</urlset>")
  if ($i -lt 0) { throw "No </urlset> in sitemap.xml" }
  $sm = $sm.Insert($i, $entry)
  [System.IO.File]::WriteAllText($smPath, $sm, $utf8)
  Write-Host "sitemap.xml entry added" -ForegroundColor Yellow
}

# ---- 4. Review, commit, push ----
git add $slug blog.html sitemap.xml
git diff --cached --stat
git commit -m "Add 6 Types of Fried Fish article, blog card and sitemap entry"
git pull --rebase --autostash
git push origin main

# ---- 5. Verify live (GET + content match) ----
Start-Sleep -Seconds 25
$chk = @(
  @{u="$base/$slug";        m="DOWNLOAD INFOGRAPHIC"},
  @{u="$base/blog.html";    m=$slug},
  @{u="$base/sitemap.xml";  m=$slug}
)
foreach ($c in $chk) {
  try {
    $r = Invoke-WebRequest -Uri $c.u -UseBasicParsing
    Write-Host ($c.u + "  status=" + $r.StatusCode + "  match=" + $r.Content.Contains($c.m)) -ForegroundColor Yellow
  } catch { Write-Host ($c.u + "  FAILED: " + $_.Exception.Message) -ForegroundColor Red }
}
